# Let me visualize each color's pattern more clearly
def print_color_pattern(color):
    cells = get_cells(color)
    min_r, max_r = min(r for r, c in cells), max(r for r, c in cells)
    min_c, max_c = min(c for r, c in cells), max(c for r, c in cells)
    print(f"\n=== Color {color} ===")
    for r in range(min_r, max_r + 1):
        row_str = ""
        for c in range(min_c, max_c + 1):
            if grid[r][c] == color:
                row_str += "#"
            else:
                row_str += "."
        print(row_str)

for color in [0, 1, 2, 6, 7, 8]:
    print_color_pattern(color)

# Check for symmetry in the grid
def is_horizontal_mirror(grid, axis_row):
    for c in range(width):
        for r in range(axis_row + 1):
            if grid[r][c] != grid[height - 1 - r + axis_row][c]:
                return False
    return True

def is_vertical_mirror(grid, axis_col):
    for r in range(height):
        for c in range(axis_col + 1):
            if grid[r][c] != grid[r][width - 1 - c + axis_col]:
                return False
    return True

print("Checking symmetries...")
print(f"Any horizontal mirror lines? Testing rows 11, 10, 9...")
for row in range(10, height // 2 + 10):
    result = is_horizontal_mirror(grid, row)
    if result:
        print(f"Found horizontal mirror at row {row}!")

print(f"\nAny vertical mirror lines?")
for col in range(12):
    result = is_vertical_mirror(grid, col)
    if result:
        print(f"Found vertical mirror at col {col}!")

# Check for simple mirror symmetries
def is_horizontal_mirror(grid):
    mid = height // 2
    for r in range(mid):
        for c in range(width):
            if grid[r][c] != grid[height - 1 - r][c]:
                return False
    return True

def is_vertical_mirror(grid):
    mid = width // 2
    for r in range(height):
        for c in range(mid):
            if grid[r][c] != grid[r][width - 1 - c]:
                return False
    return True

print(f"Horizontal mirror: {is_horizontal_mirror(grid)}")
print(f"Vertical mirror: {is_vertical_mirror(grid)}")

# Also check for rotational symmetry
def is_rotational_180(grid):
    for r in range(height):
        for c in range(width):
            if grid[r][c] != grid[height - 1 - r][width - 1 - c]:
                return False
    return True

print(f"Rotational 180: {is_rotational_180(grid)}")

# Calculate what the "completed rectangle" version would look like for each color
def compute_completed_rectangles(grid):
    result = [[9 for _ in range(width)] for _ in range(height)]
    for color in [0, 1, 2, 6, 7, 8]:
        cells = get_cells(color)
        if not cells:
            continue
        min_r, max_r = min(r for r, c in cells), max(r for r, c in cells)
        min_c, max_c = min(c for r, c in cells), max(c for r, c in cells)
        # Fill the entire bounding box with this color
        for r in range(min_r, max_r + 1):
            for c in range(min_c, max_c + 1):
                result[r][c] = color
    return result

completed = compute_completed_rectangles(grid)

# Convert back to string representation
def grid_to_str(result_grid):
    return '\n'.join(' '.join(str(x) for x in row) for row in result_grid)

print("Completed rectangles hypothesis:")
print(grid_to_str(completed))

# Try filling bboxes only into background space (not overwriting other colors)
def compute_expand_into_background(grid):
    result = [[cell for cell in row] for row in grid]  # Start as copy

    # Process each color except background
    for color in [0, 1, 2, 6, 7, 8]:
        cells = get_cells(color)
        if not cells:
            continue
        min_r, max_r = min(r for r, c in cells), max(r for r, c in cells)
        min_c, max_c = min(c for r, c in cells), max(c for r, c in cells)

        # Fill bbox cells that are currently background
        for r in range(min_r, max_r + 1):
            for c in range(min_c, max_c + 1):
                if result[r][c] == 9:
                    result[r][c] = color

    return result

expand_bg = compute_expand_into_background(grid)
print("Expand into background output:")
print(grid_to_str(expand_bg))

